"use client";

import { useEffect, useRef, useState } from "react";
import { VoiceKeyToast } from "@/components/voice-key-toast";
import { ArrowUp, Check, Mic, X } from "lucide-react";
import { useAiAccess } from "@/lib/ai/use-ai-access";
import { useVoiceInput, VOICE_MAX_SECONDS } from "@/lib/ai/use-voice-input";
import { VOICE_NEEDS_OPENAI_KEY } from "@/lib/ai/voice-access";

const clock = (ms: number) => { const seconds = Math.floor(ms / 1000); return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`; };

export function VoiceInput({ onSend, onDone, disabled = false, compact = false }: {
  onSend: (text: string) => void; onDone: (text: string) => void; disabled?: boolean; compact?: boolean;
}) {
  const voice = useVoiceInput((action, text) => action === "send" ? onSend(text) : onDone(text));
  const { status, start } = voice;
  const mic = useRef<HTMLButtonElement>(null);
  const done = useRef<HTMLButtonElement>(null);
  const words = useRef<HTMLParagraphElement>(null);
  const wasActive = useRef(false);
  const [now, setNow] = useState(0);
  const access = useAiAccess();
  const [needsKey, setNeedsKey] = useState(false);
  useEffect(() => {
    if (status === "recording") done.current?.focus();
    if (status === "idle" && wasActive.current && (!document.activeElement || document.activeElement === document.body)) mic.current?.focus();
    wasActive.current = status !== "idle";
    if (status !== "recording") return;
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, [status]);
  useEffect(() => { words.current?.scrollTo({ top: words.current.scrollHeight }); }, [voice.text]);

  const active = status !== "idle";
  const icon = compact ? "size-8" : "size-9";
  const action = "inline-flex size-9 items-center justify-center rounded-xl text-sm font-medium transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ai disabled:opacity-40";
  const label = status === "starting" ? "Starting the microphone…" : status === "finishing" ? "Finishing…" : "Listening…";
  return <>
    <button ref={mic} type="button" onClick={() => { if (access?.voice === false) setNeedsKey(true); else void start(); }} onContextMenu={event => event.preventDefault()} disabled={disabled || active}
      aria-label="Talk: record a voice message" title={access?.voice === false ? VOICE_NEEDS_OPENAI_KEY : "Talk"} className={`flex shrink-0 touch-manipulation items-center justify-center rounded-lg text-muted-foreground transition-colors select-none hover:bg-muted hover:text-foreground focus-visible:outline-2 focus-visible:outline-ai disabled:opacity-40 ${access?.voice === false ? "opacity-60" : ""} ${icon}`}>
      <Mic className="size-4" aria-hidden="true" /></button>
    {needsKey && <VoiceKeyToast onDismiss={() => setNeedsKey(false)} />}
    {voice.error && !active && <p role="alert" className="absolute bottom-full left-0 mb-2 flex max-w-full items-center gap-2 rounded-lg border border-danger/30 bg-danger-soft py-1 pr-1 pl-3 text-xs text-danger shadow-sm">
      {voice.error}<button type="button" onClick={voice.cancel} aria-label="Dismiss" className="grid size-7 place-items-center rounded-md hover:bg-danger/10"><X className="size-3.5" aria-hidden="true" /></button></p>}
    {active && <div role="group" aria-label="Voice message" onKeyDown={event => { if (event.key === "Escape") { event.preventDefault(); event.stopPropagation(); voice.cancel(); } }}
      className="absolute inset-0 z-10 flex min-h-28 flex-col gap-2 rounded-2xl border border-ai-border bg-card p-2.5 shadow-[0_0_0_3px_var(--color-ai-soft)]">
      <p ref={words} aria-live="polite" className={`min-h-0 flex-1 overflow-y-auto px-1 whitespace-pre-wrap ${compact ? "text-sm" : "text-[15px]"} ${voice.text ? "" : "text-muted-foreground"}`}>{voice.text || label}</p>
      <div className="flex items-center gap-2">
        <span className="flex items-center gap-2 pl-1" aria-hidden="true"><span className={`size-2 rounded-full bg-danger ${status === "recording" ? "motion-safe:animate-pulse" : "opacity-40"}`} />
          <span className="flex h-6 items-center gap-[3px]">{[0.45, 0.7, 1, 0.8, 0.55, 0.35].map((scale, index) =>
            <span key={index} className="w-[3px] rounded-full bg-ai transition-[height] duration-100" style={{ height: `${4 + Math.round(voice.level * scale * 18)}px` }} />)}</span></span>
        <span className="font-mono text-xs text-muted-foreground"><span className="sr-only">Recording </span>{clock(status === "recording" ? Math.max(0, now - voice.startedAt) : 0)} / {clock(VOICE_MAX_SECONDS * 1000)}</span>
        <span className="ml-auto" />
        <button type="button" onClick={() => { voice.cancel(); mic.current?.focus(); }} aria-label="Cancel and discard recording" title="Cancel" className={`${action} text-muted-foreground hover:bg-muted hover:text-foreground`}><X className="size-4" aria-hidden="true" /></button>
        <button ref={done} type="button" onClick={() => void voice.done()} disabled={status !== "recording"} aria-label="Done: put the words in the box to edit" title="Edit before sending" className={`${action} border border-input hover:bg-muted`}><Check className="size-4" aria-hidden="true" /></button>
        <button type="button" onClick={() => void voice.send()} disabled={status !== "recording"} aria-label="Send now" title="Send" className={`${action} bg-primary text-primary-foreground hover:opacity-90`}><ArrowUp className="size-4" aria-hidden="true" /></button>
      </div>
    </div>}
  </>;
}
import { afterEach, beforeEach, expect, it, vi } from "vitest";
import { level, pcm16Base64, startVoiceRecording } from "./voice-recorder";

class FakeSocket {
  static CONNECTING = 0; static OPEN = 1; static CLOSING = 2; static CLOSED = 3;
  static last: FakeSocket | null = null;
  readyState = FakeSocket.CONNECTING;
  sent: { type: string; audio?: string }[] = [];
  onopen: (() => void) | null = null; onmessage: ((event: { data: string }) => void) | null = null;
  onerror: (() => void) | null = null; onclose: (() => void) | null = null;
  constructor(public url: string, public protocols: string[]) { FakeSocket.last = this; }
  send(message: string) { this.sent.push(JSON.parse(message)); }
  close() { this.readyState = FakeSocket.CLOSED; }
  open() { this.readyState = FakeSocket.OPEN; this.onopen?.(); }
  emit(event: object) { this.onmessage?.({ data: JSON.stringify(event) }); }
}
const audio = vi.hoisted(() => ({ state: "running", closed: 0, processor: null as null | { onaudioprocess: ((event: unknown) => void) | null } }));
class FakeAudioContext {
  sampleRate = 48000; destination = {};
  get state() { return audio.closed ? "closed" : audio.state; }
  resume() { return Promise.resolve(); }
  close() { audio.closed++; return Promise.resolve(); }
  createMediaStreamSource() { return { connect: vi.fn() }; }
  createGain() { return { gain: { value: 1 }, connect: vi.fn() }; }
  createScriptProcessor() { audio.processor = { onaudioprocess: null }; return Object.assign(audio.processor, { connect: vi.fn() }); }
}
const track = { stop: vi.fn() };
const getUserMedia = vi.fn();
const fetchMock = vi.fn();
